import type { Request, Response } from 'express'
import { requireUser } from '../../middleware/authenticate.js'
import * as authService from './auth.service.js'
import { env } from '../../config/env.js'


const REFRESH_COOKIE = "refresh_token";
const REFRESH_COOKIE_PATH = "/api/auth/";

const refreshCookieOptions = {
  httpOnly: true,
  secure: process.env.NODE_ENV === "production",
  sameSite: "lax" as const,
  path: REFRESH_COOKIE_PATH,
};

function setRefreshCookie(res: Response, refresh: string) {
  res.cookie(REFRESH_COOKIE, refresh, {
    ...refreshCookieOptions,
    // Match the backend's configured refresh-token lifetime.
    maxAge: env.REFRESH_TOKEN_LIFETIME_DAYS * 24 * 60 * 60 * 1000, // days to milliseconds
  });
}

function clearRefreshCookie(res: Response) {
  res.clearCookie(REFRESH_COOKIE, refreshCookieOptions);
}

function readRefreshCookie(req: Request): string | undefined {
  const cookieHeader = req.headers.cookie;
  if (!cookieHeader) return undefined;

  const prefix = `${REFRESH_COOKIE}=`;
  const entry = cookieHeader
    .split(";")
    .map((cookie) => cookie.trim())
    .find((cookie) => cookie.startsWith(prefix));

  if (!entry) return undefined;

  try {
    return decodeURIComponent(entry.slice(prefix.length));
  } catch {
    return undefined;
  }
}


export async function login(req: Request, res: Response): Promise<void> {
  const tokens = await authService.login(req.body);

  setRefreshCookie(res, tokens.refresh);
  res.json({ access: tokens.access });
}

export async function register(req: Request, res: Response): Promise<void> {
  const tokens = await authService.register(req.body);

  setRefreshCookie(res, tokens.refresh);
  res.status(201).json({ access: tokens.access });
}

export async function me(req: Request, res: Response): Promise<void> {
  res.json(authService.serializeUser(requireUser(req)))
}

export async function updateMe(req: Request, res: Response): Promise<void> {
  res.json(await authService.updateProfile(requireUser(req), req.body))
}

export async function changePassword(req: Request, res: Response): Promise<void> {
  await authService.changePassword(requireUser(req), req.body)
  res.json({ detail: 'Password changed successfully.' })
}

